8 · Code by Zapier › Run JavaScript ("Score"): Input Data budget = [6. weekly_budget]; type = [6. type]; zone = [7. Value]; start_date = [6. start_date]; is_spam = [6. is_spam]. Code:
// Input Data: budget, type, zone, start_date, is_spam
const budget = Number(inputData.budget) || 0;
let score = 0;
if (budget >= 200000) score += 3;
else if (budget >= 100000) score += 2;
else if (budget > 0) score += 1;
if (["hotel", "caterer", "restaurant"].includes((inputData.type || "").toLowerCase())) score += 2;
if (inputData.zone === "inside") score += 2;
const start = inputData.start_date ? new Date(inputData.start_date) : null;
const days = start ? (start - new Date()) / 86400000 : null;
if (days !== null && days <= 30) score += 1;   // includes "now" and ASAP
const spam = String(inputData.is_spam).toLowerCase() === "true";
const tier = spam ? "spam" : score >= 7 ? "hot" : score >= 4 ? "warm" : "cold";
output = { score: spam ? 0 : score, tier };
